var XY_API_ROOT = "https://full.hnxianxin.cn/qd/";
var XY_COVER_ROOT = "https://bookcover.yuewen.com/qdbimg/349573/";

var XY_TEXT_SITES = { 11: 1, 12: 1, 4: 1 };
var XY_QUERY_NAMES = {
  categoryid: "category_id",
  subcategoryid: "subcategory_id",
  classid: "class_id",
  actionstatus: "action_status",
  wordscount: "words_count",
  paidmode: "paid_mode",
  tagtype: "tag_type",
  great: "great",
  endure: "endure",
  tagid: "tag_ids",
};
var XY_FILTER_TITLES = {
  actionstatus: "连载状态",
  wordscount: "字数范围",
  paidmode: "付费模式",
  tagtype: "标签匹配",
  classid: "标签筛选",
  great: "精品筛选",
  endure: "耐看筛选",
};

function xyBridge(ctx) {
  if (ctx && ctx.java) return ctx.java;
  if (typeof java !== "undefined") return java;
  return null;
}

function xySource(ctx) {
  if (ctx && ctx.source) return ctx.source;
  if (typeof source !== "undefined") return source;
  return null;
}

function xyState(ctx) {
  var holder = xySource(ctx);
  var state = {};
  try {
    state = JSON.parse(holder.getVariable() || "{}");
  } catch (error) {
    state = {};
  }
  if (!state || typeof state !== "object") state = {};
  if (state.xySite === "男站") state.xySite = "男生";
  if (state.xySite === "女站") state.xySite = "女生";
  if (!state.xySite || !XY_TEXT_SITES[String(xySiteIdByName(state.xySite))])
    state.xySite = "男生";
  if (!state.xyOrderName || state.xyOrderName === "默认榜单")
    state.xyOrderName = "人气最高";
  if (!state.xyCategoryName) state.xyCategoryName = "全部";
  if (!state.xyActionStatusName) state.xyActionStatusName = "不限";
  if (!state.xyWordsCountName) state.xyWordsCountName = "不限";
  if (!state.xyPaidModeName) state.xyPaidModeName = "不限";
  if (!state.xyTagTypeName) state.xyTagTypeName = "包含任意已选标签";
  if (!state.xyGreatName) state.xyGreatName = "不限";
  if (!state.xyEndureName) state.xyEndureName = "不限";
  if (!state.xyTagValue) state.xyTagValue = "";
  if (state.xyShowPara !== false) state.xyShowPara = true;
  if (state.xyShowChapter !== false) state.xyShowChapter = true;
  if (state.xyLargeBubble !== false) state.xyLargeBubble = true;
  if (state.xyFullComment !== true) state.xyFullComment = false;
  if (state.xyCustomMode !== true) state.xyCustomMode = false;
  state.xyYwkey = String(state.xyYwkey || "");
  state.xyYwguid = String(state.xyYwguid || "");
  state.xyUserToken = String(state.xyUserToken || "");
  state.xyAndroidId = String(state.xyAndroidId || "");
  state.xyUserName = String(state.xyUserName || "");
  state.xyUserLevel = String(state.xyUserLevel || "");
  return state;
}

function xySiteIdByName(name) {
  if (name === "女生") return 12;
  if (name === "出版") return 4;
  return 11;
}

function xyGet(ctx, key, fallback) {
  var state = xyState(ctx);
  return Object.prototype.hasOwnProperty.call(state, key)
    ? state[key]
    : fallback;
}

function xyAjax(ctx, url) {
  var bridge = xyBridge(ctx);
  if (!bridge) throw new Error("java context is unavailable");
  return bridge.ajax(url);
}

function xyJson(ctx, url) {
  return JSON.parse(xyAjax(ctx, url));
}

function xySearchUrl(ctx, keyword, page) {
  var value = String(keyword || "").replace(/^\s+|\s+$/g, "");
  var pageNumber = Math.max(1, parseInt(String(page || "1"), 10) || 1);
  return (
    XY_API_ROOT +
    "search.php?keyword=" +
    encodeURIComponent(value) +
    "&site=1&page=" +
    pageNumber +
    "&page_size=20"
  );
}

function xyDetailUrl(ctx, id) {
  return (
    XY_API_ROOT + "detail.php?bookId=" + encodeURIComponent(String(id || ""))
  );
}

function xyCatalogUrl(ctx, id) {
  return (
    XY_API_ROOT + "catalog.php?bookId=" + encodeURIComponent(String(id || ""))
  );
}

function xyCoverUrl(ctx, id) {
  return XY_COVER_ROOT + encodeURIComponent(String(id || "")) + "/180";
}

function xyNormalizeBase64(value) {
  var encoded = String(value || "").replace(/\s+/g, "");
  encoded = encoded.replace(/-/g, "+").replace(/_/g, "/");
  while (encoded.length % 4) encoded += "=";
  return encoded;
}

function xyDecodeChapter(ctx, value) {
  var text = String(value || "");
  try {
    text = decodeURIComponent(text);
  } catch (error) {}
  if (text.charAt(0) === "{") return JSON.parse(text);
  var match = text.match(/base64,([A-Za-z0-9+\/=_%-]+)/i);
  var encoded = match ? match[1] : text;
  if (!encoded) throw new Error("章节地址无效");
  var separator = encoded.indexOf(",");
  if (separator >= 0) encoded = encoded.substring(0, separator);
  var json = xyBridge(ctx).base64Decode(xyNormalizeBase64(encoded));
  var data = JSON.parse(json);
  if (
    !data ||
    !data.bookId ||
    data.chapterId === undefined ||
    data.chapterId === null ||
    data.chapterId === ""
  ) {
    throw new Error("章节信息无效");
  }
  if (
    !Object.prototype.hasOwnProperty.call(data, "time") ||
    !/^\d+$/.test(String(data.time))
  ) {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  if (String(data.time) === "0") {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  return data;
}

function xyChapterPayload(ctx, value) {
  return String(xyBridge(ctx).hexDecodeToString(String(value || "")) || "");
}

function xyCustomHeaders(ctx) {
  var state = xyState(ctx);
  if (!state.xyCustomMode || !state.xyYwkey || !state.xyYwguid) return null;
  return { Ywkey: String(state.xyYwkey), Ywguid: String(state.xyYwguid) };
}
function xyUserAndroidId(ctx, state) {
  var value = String(state.xyAndroidId || "").replace(/^\s+|\s+$/g, "");
  if (value) return value;
  try { if (xyBridge(ctx).androidId) value = String(xyBridge(ctx).androidId() || ""); } catch (error) {}
  if (!value) {
    var chars = "0123456789abcdef";
    for (var index = 0; index < 16; index++) value += chars.charAt(Math.floor(Math.random() * 16));
  }
  return value.toUpperCase();
}
function xyEnsureUser(ctx) {
  var state = xyState(ctx);
  if (state.xyCustomMode || state.xyUserToken) return state;
  var androidId = xyUserAndroidId(ctx, state);
  var options = {method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({android_id:androidId})};
  var response = JSON.parse(xyAjax(ctx, XY_API_ROOT + "user_api.php?action=guest," + JSON.stringify(options)));
  if (response.error) throw new Error(response.error);
  var user = response.user || {};
  state.xyAndroidId = androidId;
  state.xyUserToken = String(response.token || "");
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  var holder = xySource(ctx);
  if (holder && holder.setVariable) holder.setVariable(JSON.stringify(state));
  return state;
}
function xyUserHeaders(ctx) {
  var custom = xyCustomHeaders(ctx);
  if (custom) return custom;
  var state = xyEnsureUser(ctx);
  if (!state.xyUserToken) return null;
  return {"X-Sec-Token":String(state.xyUserToken),"X-Android-Id":String(state.xyAndroidId || "")};
}
function xyContentUrl(ctx, value) {
  var data = xyDecodeChapter(ctx, value);
  var vip = Number(data.v !== undefined ? data.v : data.vip) ? 1 : 0;
  var epub = Number(data.epub) ? 1 : 0;
  var url = XY_API_ROOT + "content.php?bookId=" + encodeURIComponent(String(data.bookId)) + "&chapterId=" + encodeURIComponent(String(data.chapterId)) + "&t=" + encodeURIComponent(String(data.time)) + "&epub=" + epub + "&v=" + vip;
  var headers = xyUserHeaders(ctx);
  return headers ? url + "," + JSON.stringify({headers:headers}) : url;
}

function xyQuery(ctx, url, name) {
  var match = String(url || "").match(
    new RegExp("[?&]" + name + "=([^&]+)", "i"),
  );
  if (!match) return "";
  try {
    return decodeURIComponent(match[1]);
  } catch (error) {
    return match[1];
  }
}

function xyReviewUrl(ctx, value) {
  var bookId = xyQuery(ctx, value, "bookId");
  var chapterId = xyQuery(ctx, value, "chapterId");
  var page = xyQuery(ctx, value, "page") || "1";
  return (
    XY_API_ROOT +
    "review.php?bookId=" +
    encodeURIComponent(bookId) +
    "&chapterId=" +
    encodeURIComponent(chapterId) +
    "&page=" +
    encodeURIComponent(page)
  );
}

function xyCleanText(value) {
  var images = [];
  var text = String(value || "").replace(/<img\b[^>]*>/gi, function (tag) {
    images.push(tag);
    return "\n@@XY_IMG_" + (images.length - 1) + "@@\n";
  });
  text = text
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\r\n?/g, "\n");
  return text.replace(/@@XY_IMG_(\d+)@@/g, function (all, index) {
    return images[Number(index)] || "";
  });
}

