  var title = data.Title || {};
  var common = data.CommonExt || {};
  var query = xySquareJumpQuery(title.JumpActionUrl);
  var lowerName = String(name || "").toLowerCase();
  var column = String(common.ColumnName || "");
  if (query.itemId !== undefined && query.itemId !== null) {
    return xySquareListUrl(query.itemId, "{{page}}");
  }
  if (query.filter !== undefined && query.filter !== null) {
    return xySquareRankingUrl(
      siteId,
      1,
      query.filter,
      query.categoryId,
      "{{page}}",
    );
  }
  if (
    String(title.JumpActionUrl || "").indexOf("SanJiang") >= 0 ||
    lowerName.indexOf("新书") >= 0 ||
    lowerName.indexOf("潜力") >= 0 ||
    column.indexOf("xinshu") >= 0
  ) {
    return xySquareRankingUrl(siteId, 15, "", query.categoryId, "{{page}}");
  }
  if (lowerName.indexOf("免费") >= 0) {
    return xySquareRankingUrl(siteId, 11, "paidmode:1", 0, "{{page}}");
  }
  if (lowerName.indexOf("完本") >= 0) {
    return xySquareRankingUrl(siteId, 11, "actionstatus:1", 0, "{{page}}");
  }
  return xySquareRankingUrl(siteId, 11, "", query.categoryId, "{{page}}");
}

function xyLoadSquare(ctx, state) {
  var sourceSiteId = xySiteIdByName(state.xySite);
  if (sourceSiteId !== 11 && sourceSiteId !== 12) return [];
  var siteId = xySquareSiteId(state);
  var blocks = [];
  try {
    var response = xyJson(
      ctx,
    XY_API_ROOT +
        "ranking.php?action=square&site=" +
        siteId +
        "&page=1&page_size=20",
    );
    var resultCode =
      response.Result !== undefined
        ? Number(response.Result)
        : Number(response.result || 0);
    var items = (response.Data || response.data || {}).Items || [];
    if (resultCode !== 0 || !items.length) return blocks;
    for (var index = 0; index < items.length; index++) {
      var data = items[index].Data || {};
      var name = String((data.Title || {}).Name || "").replace(
        /^\s+|\s+$/g,
        "",
      );
      if (!name) continue;
      var hasBooks = false;
      var listKeys = ["List", "BookList", "DataList", "Items", "ItemList"];
      for (var keyIndex = 0; keyIndex < listKeys.length; keyIndex++) {
        var value = data[listKeys[keyIndex]];
        if (value && value.length) hasBooks = true;
      }
      if (!hasBooks) continue;
      blocks.push({ name: name, url: xySquareBlockUrl(name, data, state) });
    }
  } catch (error) {
    try {
      xyBridge(ctx).log("起点书城分块加载失败：" + error);
    } catch (ignored) {}
  }
  return blocks;
}

function xyAddSquareBlocks(ctx, rows, state) {
  var blocks = xyLoadSquare(ctx, state);
  if (!blocks.length) return;
  xyHeader(rows, "起点书城 · " + state.xySite);
  for (var index = 0; index < blocks.length; index++) {
    xyChip(rows, blocks[index].name, blocks[index].url, false);
  }
}

function xyExplore(ctx) {
  var state = xyState(ctx);
  var config = xyLoadConfig(ctx, state);
  var categoryLine = xyConfigLine(config.lines, "categoryid");
  var categories = xyOptions(categoryLine);
  var site = xySelected(config.sites, state.xySite);
  var order = xySelected(config.orders, state.xyOrderName);
  var category = xySelected(categories, state.xyCategoryName);
  var actionStatusLine = xyConfigLine(config.lines, "actionstatus");
  var wordsCountLine = xyConfigLine(config.lines, "wordscount");
  var paidModeLine = xyConfigLine(config.lines, "paidmode");
  var tagTypeLine = xyConfigLine(config.lines, "tagtype");
  var rows = [];

  xyAddSquareBlocks(ctx, rows, state);
  xyHeader(rows, "主筛选 · 起点发现");
  xySelect(
    rows,
    "站点",
    config.sites,
    site,
    xySelectAction("xySite", "站点", ["xyCategoryName", "xySubCategoryName"], {
      分类: "全部",
      子分类: null,
    }),
    "站点",
  );
  xySelect(
    rows,
    "榜单",
    config.orders,
    order,
    xySelectAction("xyOrderName", "榜单"),
    "榜单",
  );
  xySelect(
    rows,
    "分类",
    categories,
    category,
    xySelectAction("xyCategoryName", "分类", ["xySubCategoryName"], {
      子分类: null,
    }),
    "分类",
  );
  var subcategoryOptions = xyBlankOptions(
    (category && category.Extvalue) || [],
  );
  if (subcategoryOptions.length > 1) {
    xySelect(
      rows,
      "子分类",
      subcategoryOptions,
      xySelected(subcategoryOptions, state.xySubCategoryName),
      xySelectAction("xySubCategoryName", "子分类"),
      "子类",
    );
  }
  xyActionButton(
    rows,
    "重置主筛选（恢复默认）",
    "xyResetMainExploreFilters(source, java, infoMap)",
    1,
  );

  xyHeader(rows, "扩展筛选");
  xySelect(
    rows,
    "连载状态",
    xyBlankOptions(xyOptions(actionStatusLine)),
    { Name: state.xyActionStatusName },
    xySelectAction("xyActionStatusName", "连载状态"),
    "状态",
  );
  xySelect(
    rows,
    "字数范围",
    xyBlankOptions(xyOptions(wordsCountLine)),
    { Name: state.xyWordsCountName },
    xySelectAction("xyWordsCountName", "字数范围"),
    "字数",
  );
  xySelect(
    rows,
    "付费模式",
    xyBlankOptions(xyOptions(paidModeLine)),
    { Name: state.xyPaidModeName },
    xySelectAction("xyPaidModeName", "付费模式"),
    "付费",
  );
  xySelect(
    rows,
    "标签匹配",
    xyOptions(tagTypeLine),
    { Name: state.xyTagTypeName },
    xySelectAction("xyTagTypeName", "标签匹配"),
    "匹配",
  );
  xySelect(
    rows,
    "精品",
    xyBlankOptions(xyOptions(xyConfigLine(config.filterOne, "great"))),
    { Name: state.xyGreatName },
    xySelectAction("xyGreatName", "精品"),
    "精品",
  );
  xySelect(
    rows,
    "耐看",
    xyBlankOptions(xyOptions(xyConfigLine(config.filterOne, "endure"))),
    { Name: state.xyEndureName },
    xySelectAction("xyEndureName", "耐看"),
    "耐看",
  );
  xyActionButton(
    rows,
    "重置扩展筛选",
    "xyResetExtendedExploreFilters(source, java, infoMap)",
    1,
  );

  xyHeader(rows, "结果操作");
  xyEntry(rows, "当前结果", xyRankingUrl(config, state, "{{page}}"), 1);

  xyAddTagChips(rows, config, state);

  if (!config.valid) {
    xyHeader(rows, "配置接口暂不可用，当前使用默认榜单");
  }
  return JSON.stringify(rows);
}

source.loginUrl:
function login(){}
function xyLoginState() {
  var state = {};
  try {
    state = JSON.parse(source.getVariable() || "{}");
  } catch (error) {
    state = {};
  }
  if (!state || typeof state !== "object") state = {};
  if (state.xySite === "男站") state.xySite = "男生";
  if (state.xySite === "女站") state.xySite = "女生";
  if (
    state.xySite !== "男生" &&
    state.xySite !== "女生" &&
    state.xySite !== "出版"
  )
    state.xySite = "男生";
  if (!state.xyOrderName || state.xyOrderName === "默认榜单")
    state.xyOrderName = "人气最高";
  if (!state.xyCategoryName) state.xyCategoryName = "全部";
  if (state.xyShowPara !== false) state.xyShowPara = true;
  if (state.xyShowChapter !== false) state.xyShowChapter = true;
  if (state.xyLargeBubble !== false) state.xyLargeBubble = true;
  if (state.xyFullComment !== true) state.xyFullComment = false;
  if (state.xyCustomMode !== true) state.xyCustomMode = false;
  state.xyYwkey = String(state.xyYwkey || "");
  state.xyYwguid = String(state.xyYwguid || "");
  state.xyUserToken = String(state.xyUserToken || "");
  state.xyGuestAuthor = String(state.xyGuestAuthor || "");
  state.xyGuestGroup = String(state.xyGuestGroup || "");
  state.xyGuestPass = String(state.xyGuestPass || "");
  state.xyGuestVerified = state.xyGuestVerified === true;
  state.xyAndroidId = String(state.xyAndroidId || "");
  state.xyUserName = String(state.xyUserName || "");
  state.xyUserLevel = String(state.xyUserLevel || "");
  return state;
}

function xyLoginSave(state) {
  source.setVariable(JSON.stringify(state));
  try {
    java.reLoginView();
  } catch (error) {}
}


function xyLoginAndroidId(state) {
  var value = "";
  try { value = String(java.androidId() || "").replace(/^\s+|\s+$/g, ""); } catch (error) {}
  if (!value) value = String((state && state.xyAndroidId) || "").replace(/^\s+|\s+$/g, "");
  if (!value) {
    var chars = "0123456789abcdef";
    for (var index = 0; index < 16; index++) value += chars.charAt(Math.floor(Math.random() * 16));
  }
  return value.toUpperCase();
}
function xyLoginRequest(action, data) {
  var options = {method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(data || {})};
  var response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=" + action + "," + JSON.stringify(options)));
  if (response.error) throw new Error(response.error);
  return response;
}
function xyLoginStoreAuth(state, response, androidId) {
  var user = response.user || {};
  state.xyAndroidId = String(androidId || xyLoginAndroidId(state));
  state.xyUserToken = String(response.token || "");
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  state.xyCustomMode = false;
  xyLoginSave(state);
  return user;
}
function xyLoginGuest() {
  var state = xyLoginState();
  var sourceAuthor = xyLoginFieldValue("源作者");
  var feedbackGroup = xyLoginFieldValue("官方反馈群");
  var temporaryPassword = xyLoginFieldValue("临时口令");
  state.xyGuestAuthor = sourceAuthor;
  state.xyGuestGroup = feedbackGroup;
  state.xyGuestPass = temporaryPassword;
  source.setVariable(JSON.stringify(state));
  xyLoginSaveGuestFields(sourceAuthor, feedbackGroup, temporaryPassword);
  if (!sourceAuthor || !feedbackGroup || !temporaryPassword)
    return java.toast("请手动填写源作者、官方反馈群和临时口令");
  var androidId = xyLoginAndroidId(state);
  var response;
  try {
    response = xyLoginRequest("guest", {
      source_author: sourceAuthor,
      feedback_group: feedbackGroup,
      temporary_password: temporaryPassword,
      android_id: androidId
    });
  } catch (error) {
    return java.toast(String((error && error.message) || error));
  }
  state.xyGuestVerified = true;
  var user = xyLoginStoreAuth(state, response, androidId);
  java.toast("游客授权成功：" + String(user.privilege || ""));
}
function xyLoginFieldValue(name) {
  return String((result && result.get(name)) || "").replace(/^\s+|\s+$/g, "");
}

function xyLoginSaveGuestFields(sourceAuthor, feedbackGroup, temporaryPassword) {
  try {
    var loginInfo = {};
    try {
      loginInfo = JSON.parse(source.getLoginInfo() || "{}");
    } catch (error) {}
    loginInfo["源作者"] = sourceAuthor;
    loginInfo["官方反馈群"] = feedbackGroup;
    loginInfo["临时口令"] = temporaryPassword;
    source.putLoginInfo(JSON.stringify(loginInfo));
    try {
      java.upLoginData(loginInfo);
    } catch (error) {}
  } catch (error) {}
}

function xyLoginWeb() { 
  var state = xyLoginState();
  var androidId = xyLoginAndroidId(state);
  state.xyAndroidId = androidId;
  xyLoginSave(state);
  var preload = [
    "window.xySaveLegadoAuth = function(payload) {",
    "  var state = {};",
    "  try { state = JSON.parse(source.getVariable() || '{}'); } catch (error) { state = {}; }",
    "  var user = (payload && payload.user) || {};",
    "  state.xyUserToken = String((payload && payload.token) || '');",
    "  state.xyAndroidId = String((payload && payload.android_id) || state.xyAndroidId || '');",
    "  state.xyUserName = String(user.username || '');",
    "  state.xyUserLevel = String(user.level || 'guest');",
    "  state.xyCustomMode = false;",
    "  var encoded = JSON.stringify(state);",
    "  try { source.putVariable(encoded); } catch (error) { try { source.setVariable(encoded); } catch (ignored) {} }",
    "  setTimeout(function(){ try { if (java.reLoginView) java.reLoginView(true); } catch (error) {} try { window.close(); } catch (error) {} }, 1500);",
    "  return true;",
    "};"
  ].join("\n");
  java.showBrowser(XY_API_ROOT + "auth.php?mode=legado&android_id=" + encodeURIComponent(androidId), null, preload);

}
function xyLoginUserCenter() {
  var state = xyLoginState();
  var token = String(state.xyUserToken || "");
  var androidId = String(state.xyAndroidId || "");
  var preload = [
    "try { localStorage.setItem('qidian-user-token', " + JSON.stringify(token) + "); } catch (e) {}",
    "try { localStorage.setItem('qidian-android-id', " + JSON.stringify(androidId) + "); } catch (e) {}"
  ].join("\n");
  try { java.showBrowser(XY_API_ROOT + "account.php", null, preload); }
  catch (error) { java.toast("无法打开用户中心：" + String(error)); }
}
function xyLoginSyncAuth() {
  var state = xyLoginState();
  if (!state.xyUserToken) {
    xyLoginSave(state);
    java.toast("当前尚未授权");
    return;
  }
  var options = {method:"GET",headers:{Accept:"application/json","X-Sec-Token":state.xyUserToken,"X-Android-Id":state.xyAndroidId}};
  var response;
  try {
    response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=me," + JSON.stringify(options)));
  } catch (error) {
    xyLoginSave(state);
    java.toast("授权状态同步失败，请稍后重试");
    return;
  }
  if (response.error) {
    state.xyUserToken = "";
    state.xyUserName = "";
    state.xyUserLevel = "";
    state.xyGuestVerified = false;
    xyLoginSave(state);
    java.toast("授权已失效，请重新登录");
    return;
  }
  var user = response.user || {};
  state.xyUserToken = String(response.token || state.xyUserToken);
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  xyLoginSave(state);
  java.toast("授权状态已同步：" + (user.username || "游客用户"));
}
function xyLoginUsage() {
  var state = xyLoginState();
  if (!state.xyUserToken) return java.toast("请先申请游客 Token 或登录账号");
  var options = {method:"GET",headers:{Accept:"application/json","X-Sec-Token":state.xyUserToken,"X-Android-Id":state.xyAndroidId}};
  var response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=me," + JSON.stringify(options)));
  if (response.error) return java.toast(response.error);
  var user = response.user || {};
  java.longToast("\n用户：" + (user.username || "游客用户") + "\n等级：" + (user.level_name || "--") + "\n权益：" + (user.privilege || "--") + "\n今日：" + Number(user.today_count || 0) + "\n昨日：" + Number(user.yesterday_count || 0) + "\n累计：" + Number(user.total_count || 0));
}
function xyLoginExit() {
  var state = xyLoginState();
  if (!state.xyUserToken) return;
  xyLoginRequest("logout", {});
  state.xyUserToken = "";
  state.xyUserName = "";
  state.xyUserLevel = "";
  xyLoginSave(state);
  java.toast("已退出用户系统");
}

function xyLoginTogglePara() {
  var state = xyLoginState();
  state.xyShowPara = !state.xyShowPara;
  xyLoginSave(state);
  java.toast(
    "段评已" + (state.xyShowPara ? "开启" : "关闭") + "，请刷新当前章节",
  );
}

function xyLoginToggleChapter() {
  var state = xyLoginState();
  state.xyShowChapter = !state.xyShowChapter;
  xyLoginSave(state);
  java.toast(
    "章评已" + (state.xyShowChapter ? "开启" : "关闭") + "，请刷新当前章节",
  );
}

function xyLoginToggleLargeBubble() {
  var state = xyLoginState();
  state.xyLargeBubble = !state.xyLargeBubble;
  xyLoginSave(state);
  java.toast(
    "段评气泡已切换为" +
      (state.xyLargeBubble ? "大气泡" : "小气泡") +
      "，请刷新当前章节",
  );
}

function xyLoginToggleCommentScreen() {
  var state = xyLoginState();
  state.xyFullComment = !state.xyFullComment;
  xyLoginSave(state);
  java.toast("段评已切换为" + (state.xyFullComment ? "全屏" : "半屏"));
}

function xyLoginSaveCredential() {
  var state = xyLoginState();
  state.xyYwkey = String((result && result.get("ywkey")) || "").replace(
    /^\s+|\s+$/g,
    "",
  );
  state.xyYwguid = String((result && result.get("ywguid")) || "").replace(
    /^\s+|\s+$/g,
    "",
  );
  xyLoginSave(state);
  java.toast("自订凭证已保存");
}

function xyLoginToggleCustom() {
  var state = xyLoginState();
  if (!state.xyCustomMode && (!state.xyYwkey || !state.xyYwguid)) {
    java.toast("请先填写并保存 ywkey 与 ywguid");
    return;
  }
  state.xyCustomMode = !state.xyCustomMode;
  xyLoginSave(state);
  java.toast(
    "自订模式已" +
      (state.xyCustomMode ? "开启" : "关闭") +
      "，请刷新目录后生效",
  );
}

function xyLoginUi() {
  var state = xyLoginState();
  var rows = [];

  function button(name, action, fullWidth) {
    rows.push({
      title: "",
      url: "",
      name: name,
      type: "button",
      action: action,
      style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: fullWidth ? 1 : 0.45,
      },
    });
  }

  function label(name) {
    button("—— " + name + " ——", "void 0;", true);
  }

  label("正文用户系统");
  rows.push({title:"",url:"",name:"源作者",type:"text",default:state.xyGuestAuthor || "",style:{layout_flexGrow:1,layout_flexBasisPercent:1}});
  rows.push({title:"",url:"",name:"官方反馈群",type:"text",default:state.xyGuestGroup || "",style:{layout_flexGrow:1,layout_flexBasisPercent:1}});
  rows.push({title:"",url:"",name:"临时口令",type:"text",default:state.xyGuestPass || "",style:{layout_flexGrow:1,layout_flexBasisPercent:1}});
  button(state.xyUserToken ? "✅ 已授权：" + (state.xyUserName || state.xyUserLevel || "guest") : "⬜ 尚未授权", "xyLoginSyncAuth()");
  button("申请游客Token", "xyLoginGuest()");
  button("网页注册/登录", "xyLoginWeb()");
  button("查看使用次数", "xyLoginUsage()");
  button("用户中心", "xyLoginUserCenter()");
  button("同步授权状态", "xyLoginSyncAuth()");
  button("退出用户系统", "xyLoginExit()");

  label("自订正文凭证");
  rows.push({
    title: "",
    url: "",
    name: "ywkey",
    type: "text",
    default: state.xyYwkey || "",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 },
  });
  rows.push({
    title: "",
    url: "",
    name: "ywguid",
    type: "text",
    default: state.xyYwguid || "",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 },
  });
  button(
    state.xyCustomMode ? "✅ 自订模式已开启" : "⬜ 自订模式已关闭",
    "xyLoginToggleCustom()",
  );
  button("保存自订凭证", "xyLoginSaveCredential()");

  label("阅读评论");
  button(
    state.xyShowPara ? "✅ 段评气泡" : "⬜ 段评气泡",
    "xyLoginTogglePara()",
  );
  button(
    state.xyLargeBubble ? "✅ 大气泡（TEXT）" : "⬜ 小气泡（text）",
    "xyLoginToggleLargeBubble()",
  );
  button(
    state.xyShowChapter ? "✅ 章末评论" : "⬜ 章末评论",
    "xyLoginToggleChapter()",
  );
  button(
    state.xyFullComment ? "✅ 全屏段评" : "📱 半屏段评",
    "xyLoginToggleCommentScreen()",
  );

  return JSON.stringify(rows);
}

